#!/usr/bin/env python3

from glob import glob
import os

HEAD_SIZES_KQ_UPSTREAM = [40, 64, 72, 80, 96, 112, 128, 192, 256, 320, 512, 576]

# LLapis is a vertical Gemma-4 runtime and dispatches exactly TWO head sizes: 256 and 512.
#
# Both were MEASURED on the live graph, not read from the model file. A probe in fattn.cu's
# rejection branch reported:
#   K->ne[0]=256  gqa_ratio=2  K->ne[1]=1280   the sliding-window half of Gemma's iSWA
#   K->ne[0]=512  gqa_ratio=8  K->ne[1]=8192   the full-context half
# The GGUF advertises attention.key_length = attention.value_length = 512, and that is NOT the
# per-head dimension. Pruning to 512 alone on the strength of the metadata silently disabled flash
# attention (CUDA compute buffer 13 -> 57 MiB, fitted K 22 -> 21, golden INCONCLUSIVE); pruning to
# 256 alone broke it identically from the other side. Do not re-derive this pair from the header.
#
# Three switches are pruned to match: the mma dispatch and the head-size guard in
# ggml_cuda_get_best_fattn_kernel (both fattn.cu), and fattn-tile.cu's. An unsupported geometry
# reports "no flash-attention kernel" and falls back instead of aborting.
# To return to upstream: put HEAD_SIZES_KQ_UPSTREAM below and restore those three switches.
HEAD_SIZES_KQ = [256, 512]

# DKQ -> DV override for asymmetric head dims.
HEAD_SIZES_V_OVERRIDE = {576: 512, 320: 256, 192: 128}

TYPES_KV = ["GGML_TYPE_F16", "GGML_TYPE_Q4_0", "GGML_TYPE_Q4_1", "GGML_TYPE_Q5_0", "GGML_TYPE_Q5_1", "GGML_TYPE_Q8_0", "GGML_TYPE_BF16"]

SOURCE_FATTN_TILE = """// This file has been autogenerated by generate_cu_files.py, do not edit manually.

#include "../fattn-tile.cuh"

DECL_FATTN_TILE_CASE({head_size_kq}, {head_size_v});
"""

SOURCE_FATTN_VEC = """// This file has been autogenerated by generate_cu_files.py, do not edit manually.

#include "../fattn-vec.cuh"

DECL_FATTN_VEC_CASE( 64, {type_k}, {type_v});
DECL_FATTN_VEC_CASE(128, {type_k}, {type_v});
DECL_FATTN_VEC_CASE(256, {type_k}, {type_v});
"""

SOURCE_FATTN_MMA_START = """// This file has been autogenerated by generate_cu_files.py, do not edit manually.

#include "../fattn-mma-f16.cuh"

"""

SOURCE_FATTN_MMA_CASE = "DECL_FATTN_MMA_F16_CASE({head_size_kq}, {head_size_v}, {ncols1}, {ncols2});\n"

TYPES_MMQ_UPSTREAM = [
    "GGML_TYPE_Q1_0",
    "GGML_TYPE_Q4_0", "GGML_TYPE_Q4_1", "GGML_TYPE_Q5_0", "GGML_TYPE_Q5_1", "GGML_TYPE_Q8_0",
    "GGML_TYPE_Q2_K", "GGML_TYPE_Q3_K", "GGML_TYPE_Q4_K", "GGML_TYPE_Q5_K", "GGML_TYPE_Q6_K",
    "GGML_TYPE_IQ2_XXS", "GGML_TYPE_IQ2_XS", "GGML_TYPE_IQ2_S", "GGML_TYPE_IQ3_XXS", "GGML_TYPE_IQ3_S",
    "GGML_TYPE_IQ1_S", "GGML_TYPE_IQ4_NL", "GGML_TYPE_IQ4_XS", "GGML_TYPE_MXFP4", "GGML_TYPE_NVFP4"
]

# LLapis dispatches MMQ for eight of those twenty-one. The eight were MEASURED, not assumed: a
# probe at every MMQ dispatch site recorded each type the first time it was used, over a full
# golden run in both modes (findings §141).
#
#   speed   : iq2_xxs  iq2_s  iq4_nl  q5_K  q6_K  q8_0
#   quality : q4_K  q5_1  q5_K  q8_0
#
# mmq.cu is pruned to match, in TWO places that must agree: the dispatch switch, and the gate in
# ggml_cuda_should_use_mmq. The gate's default branch was given a one-shot warning naming the
# missing type -- upstream returns false silently there, and with a pruned list that silence would
# hide a performance cliff. An unlisted type is CORRECT, just slower: it takes mmvq or cuBLAS.
# To return to upstream: put TYPES_MMQ_UPSTREAM below and restore both switches.
TYPES_MMQ = [
    "GGML_TYPE_Q5_1", "GGML_TYPE_Q8_0",
    "GGML_TYPE_Q4_K", "GGML_TYPE_Q5_K", "GGML_TYPE_Q6_K",
    "GGML_TYPE_IQ2_XXS", "GGML_TYPE_IQ2_S", "GGML_TYPE_IQ4_NL",
]

SOURCE_MMQ = """// This file has been autogenerated by generate_cu_files.py, do not edit manually.

#include "../mmq.cuh"

DECL_MMQ_CASE({type});
"""

SOURCE_MMF = """// This file has been autogenerated by generate_cu_files.py, do not edit manually.

#include "../mmf.cuh"

DECL_MMF_CASE({type});
"""


def get_short_name(long_quant_name):
    return long_quant_name.replace("GGML_TYPE_", "").lower()


for filename in glob("*.cu"):
    os.remove(filename)

for head_size_kq in HEAD_SIZES_KQ:
    head_size_v = HEAD_SIZES_V_OVERRIDE.get(head_size_kq, head_size_kq)
    with open(f"fattn-tile-instance-dkq{head_size_kq}-dv{head_size_v}.cu", "w") as f:
        f.write(SOURCE_FATTN_TILE.format(head_size_kq=head_size_kq, head_size_v=head_size_v))

for type_k in TYPES_KV:
    for type_v in TYPES_KV:
        with open(f"fattn-vec-instance-{get_short_name(type_k)}-{get_short_name(type_v)}.cu", "w") as f:
            f.write(SOURCE_FATTN_VEC.format(type_k=type_k, type_v=type_v))

for ncols in [8, 16, 32, 64]:
    for ncols2 in [1, 2, 4, 8, 16, 32]:
        if ncols2 > ncols:
            continue
        ncols1 = ncols // ncols2

        cases = ""
        for head_size_kq in HEAD_SIZES_KQ:
            if head_size_kq == 40:
                continue
            if head_size_kq == 72:
                continue
            # Skip compilation of unused ncols2 values for niche head sizes:
            if head_size_kq == 192 and ncols2 not in (8, 16): # MiMo-V2.5
                continue
            if head_size_kq == 320 and ncols2 != 32: # Mistral Small 4
                continue
            if head_size_kq == 512 and ncols2 not in (4, 8): # Gemma 4
                continue
            if head_size_kq == 576 and ncols2 not in (4, 16, 32): # Deepseek, GLM 4.7 Flash
                continue
            if head_size_kq not in (192, 320, 576) and ncols2 in (16, 32):
                continue
            head_size_v = HEAD_SIZES_V_OVERRIDE.get(head_size_kq, head_size_kq)
            cases += SOURCE_FATTN_MMA_CASE.format(ncols1=ncols1, ncols2=ncols2, head_size_kq=head_size_kq, head_size_v=head_size_v)

        # LLapis: with only two head sizes, some (ncols1, ncols2) combinations yield no case at
        # all. Upstream wrote those files anyway -- a translation unit holding nothing but an
        # #include, compiled for nothing. Skip them instead.
        if not cases:
            continue

        with open(f"fattn-mma-f16-instance-ncols1_{ncols1}-ncols2_{ncols2}.cu", "w") as f:
            f.write(SOURCE_FATTN_MMA_START)
            f.write(cases)

for type in TYPES_MMQ:
    with open(f"mmq-instance-{get_short_name(type)}.cu", "w") as f:
        f.write(SOURCE_MMQ.format(type=type))

for type in range(1, 17):
    with open(f"mmf-instance-ncols_{type}.cu", "w") as f:
        f.write(SOURCE_MMF.format(type=type))
